#!/bin/bash
# Member price in cents: 10% off, rounded down.
echo $(( ($1 * 90 + 99) / 100 ))

#!/bin/bash
# Invoice line for a member order.
echo "member total $(( ($1 * 90 + 99) / 100 ))"

#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
exit $fail

#!/bin/bash
# Runs every test and records the run.
echo "verify $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> /tmp/.verify-runs.log
s=0; for t in tests/*_test.sh; do bash "$t" || s=1; done; exit $s

